import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

function DashboardStudent() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [stats, setStats] = useState({
    coursesCount: 0,
    assignmentsCount: 0,
    averageGrade: "N/A",
    pendingAssignments: 0
  });

  useEffect(() => {
    const userData = localStorage.getItem('user');
    const isAuthenticated = localStorage.getItem('isAuthenticated');
    
    if (!isAuthenticated || !userData) {
      navigate("/login");
      return;
    }

    const userObj = JSON.parse(userData);
    
    if (userObj.role !== "student") {
      alert("❌ Accès réservé aux étudiants");
      navigate("/login");
      return;
    }

    setUser(userObj);
    // Simuler des données de statistiques
    setStats({
      coursesCount: 6,
      assignmentsCount: 12,
      averageGrade: "14.5/20",
      pendingAssignments: 3
    });
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('user');
    localStorage.removeItem('isAuthenticated');
    localStorage.removeItem('userRole');
    localStorage.removeItem('token');
    navigate("/login");
  };

  // Navigation functions
  const navigateToCourses = () => {
    navigate("/mes-cours");
  };

  const navigateToGrades = () => {
    navigate("/mes-notes");
  };

  const navigateToAssignments = () => {
    navigate("/mes-devoirs");
  };

  const navigateToProfile = () => {
    navigate("/mon-profil");
  };

  if (!user) {
    return (
      <div style={styles.loadingContainer}>
        <div style={styles.spinner}></div>
        <p>Chargement des données étudiant...</p>
      </div>
    );
  }

  return (
    <div style={styles.dashboard}>
      <header style={styles.header}>
        <div style={styles.headerContent}>
          <h1 style={styles.headerTitle}>Tableau de Bord Étudiant</h1>
          <div style={styles.userInfo}>
            <span>Bienvenue, <strong>{user.nom}</strong></span>
            <div style={styles.userRole}>
              <span style={styles.roleBadge}>ÉTUDIANT</span>
              <button onClick={handleLogout} style={styles.logoutButton}>
                Déconnexion
              </button>
            </div>
          </div>
        </div>
      </header>

      <main style={styles.main}>
        <div style={styles.welcomeSection}>
          <h2 style={styles.welcomeTitle}>Bonjour, {user.nom} 🎓</h2>
          <div style={styles.userDetails}>
            <div style={styles.infoCard}>
              <h3 style={styles.infoCardTitle}>Informations Personnelles</h3>
              <p><strong>ID:</strong> {user.id}</p>
              <p><strong>Email:</strong> {user.email}</p>
              <p><strong>Rôle:</strong> {user.role}</p>
              <p><strong>Promotion:</strong> {user.promotion || "2023-2024"}</p>
            </div>
          </div>
        </div>

        <div style={styles.dashboardGrid}>
          <div style={styles.dashboardCard} onClick={navigateToCourses}>
            <div style={styles.cardIcon}>📚</div>
            <h3 style={styles.cardTitle}>Mes Cours</h3>
            <p style={styles.cardDescription}>Consulter votre emploi du temps et les matières inscrites</p>
            <button style={styles.primaryButton}>Accéder aux cours</button>
          </div>

          <div style={styles.dashboardCard} onClick={navigateToGrades}>
            <div style={styles.cardIcon}>📊</div>
            <h3 style={styles.cardTitle}>Mes Notes</h3>
            <p style={styles.cardDescription}>Consulter vos notes et résultats académiques détaillés</p>
            <button style={styles.primaryButton}>Voir mes notes</button>
          </div>

          <div style={styles.dashboardCard} onClick={navigateToAssignments}>
            <div style={styles.cardIcon}>📝</div>
            <h3 style={styles.cardTitle}>Mes Devoirs</h3>
            <p style={styles.cardDescription}>Gérer vos devoirs et travaux à rendre</p>
            <button style={styles.primaryButton}>Voir les devoirs</button>
          </div>

