// Ajout des keyframes pour l'animation du spinner
const styleSheet = document.styleSheets[0];
const keyframes = `
@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
`;
styleSheet.insertRule(keyframes, styleSheet.cssRules.length);

// Ajout des styles hover dynamiquement
Object.keys(styles).forEach(selector => {
  const style = styles[selector];
  if (style[':hover']) {
    const hoverStyle = style[':hover'];
    delete style[':hover'];
    
    const css = `
      .${selector}:hover {
        ${Object.keys(hoverStyle).map(prop => 
          `${prop}: ${hoverStyle[prop]};`
        ).join('')}
      }
    `;
    styleSheet.insertRule(css, styleSheet.cssRules.length);
  }
  
  if (style['::before']) {
    const beforeStyle = style['::before'];
    delete style['::before'];
    
    const css = `
      .${selector}::before {
        ${Object.keys(beforeStyle).map(prop => 
          `${prop}: ${beforeStyle[prop]};`
        ).join('')}
      }
    `;
    styleSheet.insertRule(css, styleSheet.cssRules.length);
